import "../../styles/index-base.css";
import "../../styles/components/alert.css";
import { Info, WarningCircle, X } from "@phosphor-icons/react";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { cn } from "../../lib/cn";
import { IconButton } from "./icon-button";

export type AlertProps = Omit<ComponentPropsWithRef<"div">, "title"> & {
  variant?: "neutral" | "critical";
  title: ReactNode;
  icon?: ReactNode;
  action?: ReactNode;
  live?: "polite" | "assertive";
  dismissLabel?: string;
  onDismiss?: () => void;
};

export function Alert({
  variant = "neutral",
  title,
  icon,
  action,
  live,
  dismissLabel = "Dismiss notification",
  onDismiss,
  className,
  children,
  role,
  ...props
}: AlertProps) {
  const fallbackIcon = variant === "critical" ? <WarningCircle weight="fill" /> : <Info weight="fill" />;

  return (
    <div
      className={cn("ix-alert", className)}
      data-variant={variant}
      role={role ?? (live === "assertive" ? "alert" : live === "polite" ? "status" : undefined)}
      aria-live={live}
      {...props}
    >
      <span className="ix-alert__icon" aria-hidden="true">{icon ?? fallbackIcon}</span>
      <span className="ix-alert__content">
        <strong>{title}</strong>
        {children && <span>{children}</span>}
      </span>
      {action && <span className="ix-alert__action">{action}</span>}
      {onDismiss && <IconButton className="ix-alert__dismiss" variant="ghost" size="small" aria-label={dismissLabel} onClick={onDismiss}><X /></IconButton>}
    </div>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-alert {
  display: grid;
  width: min(560px, 100%);
  min-height: 54px;
  grid-template-columns: 18px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 12px;
  border-radius: var(--ix-radius-md);
  background: var(--ix-bg-subtle);
  color: var(--ix-fg-default);
}

.ix-alert[data-variant="critical"] { background: color-mix(in oklch, var(--ix-fg-danger) 7%, var(--ix-bg-subtle)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ix-fg-danger) 24%, transparent); }

.ix-alert[data-variant="critical"] .ix-alert__icon { color: var(--ix-fg-danger); }

.ix-alert__icon { display: grid; width: 18px; height: 18px; place-items: center; color: var(--ix-fg-muted); }

.ix-alert__icon svg { width: 16px; height: 16px; }

.ix-alert__content { display: grid; min-width: 0; gap: 2px; }

.ix-alert__content strong { font-size: var(--ix-type-ui); font-weight: 580; letter-spacing: -0.01em; }

.ix-alert__content > span { color: var(--ix-fg-muted); font-size: var(--ix-type-label); line-height: 1.45; }

.ix-alert__action { display: inline-flex; align-items: center; }

.ix-alert__dismiss { color: var(--ix-fg-subtle); }
}
